class Solution:
    def maximumScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # left[i] is the closest val on the left where nums[l] < nums[i]
        left = [-1] * n
        stackL = []
        for i in range(n):
            while stackL and nums[stackL[-1]] >= nums[i]:
                stackL.pop()
            if stackL:
                left[i] = stackL[-1]
            stackL.append(i)

        # right[i] is the closest val on the right where nums[r] < nums[i]
        right = [n] * n
        stackR = []
        for i in range(n - 1, -1, -1):
            while stackR and nums[stackR[-1]] >= nums[i]:
                stackR.pop()
            if stackR:
                right[i] = stackR[-1]
            stackR.append(i)

        ans = 0
        for i in range(n):
            # nums[i] is the minimum throughout:
            # [left[i] + 1, right[i] - 1]
            if left[i] < k < right[i]:
                length = right[i] - left[i] - 1
                score = nums[i] * length
                ans = max(ans, score)

        return ans
